-- =====================================================================
--  Projetos de Compartilhamento de Infraestrutura
--  DDL para SAP HANA (schema de trabalho: ajuste "CLB349328" se for outro)
--
--  Segue o mesmo padrão do resto do portal:
--    - CREATE COLUMN TABLE ... UNLOAD PRIORITY 5 AUTO MERGE
--    - PK INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY
--    - texto NVARCHAR(n); data/hora LONGDATE CS_LONGDATE
--    - flags S/N em NVARCHAR(1) DEFAULT 'N'
--    - coordenadas em DECIMAL(18,10) (igual a POSTE.X / .Y e ACAO_POSTE.MIN_X)
--    - SEM foreign keys / check constraints: os domínios são validados no
--      backend, como já acontece com PROVEDOR / PROCESSO / SOLICITACAO_ACAO.
--
--  Vínculo com a jornada do provedor
--  ---------------------------------
--  O projeto chega por e-mail ANTES de existir (ou sem que se saiba) um
--  provedor/processo cadastrado. Por isso o elo é feito em duas camadas:
--
--    1. CHAVE_CONEXAO  -> chave natural, sempre preenchida: o CNPJ do
--       provedor só com dígitos (14 caracteres). É o que amarra o projeto
--       à identidade do provedor mesmo antes de haver FK resolvida.
--    2. ID_PROVEDOR / ID_PROCESSO -> FKs lógicas, preenchidas quando o
--       backend consegue casar a CHAVE_CONEXAO com
--       PORTAL_COMPARTILHAMENTO_PROVEDOR (por CNPJ) e, opcionalmente, com
--       um PORTAL_COMPARTILHAMENTO_PROCESSO daquele provedor.
--
--  Fluxo de análise (STATUS_PROJETO, validado em código):
--    RECEBIDO -> EM_ANALISE -> PENDENTE_DOC -> ANALISE_TECNICA
--             -> PARECER_EMITIDO -> VINCULADO -> CONCLUIDO
--             -> (a qualquer momento) DEVOLVIDO | CANCELADO
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1) PROJETO  (cabeçalho — 1 linha por projeto recebido)
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO"
(
    "ID_PROJETO"            INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "NUMERO_PROJETO"        NVARCHAR(40)  NOT NULL,       -- ex.: PRJ-2026-000123
    "TITULO"                NVARCHAR(200),

    -- Vínculo com a jornada do provedor
    "CHAVE_CONEXAO"         NVARCHAR(14)  NOT NULL,       -- CNPJ só dígitos
    "ID_PROVEDOR"           INTEGER,                      -- resolvido -> PROVEDOR.ID_PROVEDOR
    "ID_PROCESSO"           INTEGER,                      -- opcional -> PROCESSO.ID_PROCESSO
    "NUMERO_PROTOCOLO"      NVARCHAR(30),                 -- cópia do PROCESSO, p/ exibição

    -- Identificação do provedor (denormalizado — vem no e-mail/planilha)
    "CNPJ"                  NVARCHAR(20)  NOT NULL,       -- formatado
    "RAZAO_SOCIAL"          NVARCHAR(200) NOT NULL,
    "NOME_FANTASIA"         NVARCHAR(200),

    -- Localização principal do projeto
    "MUNICIPIO"             NVARCHAR(120),
    "UF"                    NVARCHAR(2),
    "REGIONAL"              NVARCHAR(60),

    -- Volumetria
    "QTD_POSTES_INFORMADA"  INTEGER       DEFAULT 0,      -- o que o provedor declarou
    "QTD_POSTES_RECEBIDA"   INTEGER       DEFAULT 0,      -- o que veio na planilha de postes
    "QTD_POSTES_VALIDADA"   INTEGER       DEFAULT 0,      -- aprovados na análise técnica

    -- Situação da análise
    "STATUS_PROJETO"        NVARCHAR(20)  DEFAULT 'RECEBIDO',
    "PRIORIDADE"            NVARCHAR(10)  DEFAULT 'MEDIA',
    "RESPONSAVEL_ANALISE"   NVARCHAR(100),
    "PRAZO_ANALISE"         DATE,
    "DATA_CONCLUSAO"        LONGDATE CS_LONGDATE,

    -- Origem / submissão
    "CANAL_ORIGEM"          NVARCHAR(20)  DEFAULT 'EMAIL', -- EMAIL | UPLOAD | API
    "SUBMETIDO_POR"         NVARCHAR(100),                 -- usuário do portal que registrou
    "EMAIL_REMETENTE"       NVARCHAR(200),                 -- de quem veio o e-mail
    "DATA_RECEBIMENTO"      LONGDATE CS_LONGDATE,

    -- Conferência documental (resumo rápido; detalhe em PROJETO_DOCUMENTO)
    "DOCS_OBRIGATORIOS"     INTEGER       DEFAULT 0,
    "DOCS_RECEBIDOS"        INTEGER       DEFAULT 0,
    "DOCS_VALIDADOS"        INTEGER       DEFAULT 0,
    "DOCUMENTACAO_OK"       NVARCHAR(1)   DEFAULT 'N',

    "OBSERVACOES"           NVARCHAR(4000),

    -- Auditoria
    "CREATED_AT"            LONGDATE CS_LONGDATE,
    "CREATED_BY"            NVARCHAR(100),
    "UPDATED_AT"            LONGDATE CS_LONGDATE,
    "UPDATED_BY"            NVARCHAR(100),
    "ATIVO"                 NVARCHAR(1)   DEFAULT 'S',

    PRIMARY KEY ("ID_PROJETO")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE UNIQUE INDEX "IX_PROJETO_NUMERO"   ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" ("NUMERO_PROJETO");
CREATE INDEX        "IX_PROJETO_CHAVE"    ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" ("CHAVE_CONEXAO");
CREATE INDEX        "IX_PROJETO_PROVEDOR" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" ("ID_PROVEDOR");
CREATE INDEX        "IX_PROJETO_PROCESSO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" ("ID_PROCESSO");
CREATE INDEX        "IX_PROJETO_STATUS"   ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" ("STATUS_PROJETO");


-- ---------------------------------------------------------------------
-- 2) PROJETO_POSTE  (1:N — os postes do projeto, com lat/long)
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_POSTE"
(
    "ID_PROJETO_POSTE"     INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "ID_PROJETO"           INTEGER       NOT NULL,

    -- Identificador do poste como veio na planilha do provedor
    "IDENTIFICADOR_POSTE"  NVARCHAR(60),                  -- código do provedor
    "BARRAMENTO"           NVARCHAR(50),                  -- casado com PORTAL_COMPARTILHAMENTO_POSTE.BARRAMENTO
    "ID_POSTE_PORTAL"      INTEGER,                       -- id do poste no cadastro oficial, se casou

    -- Geolocalização (mesma precisão de POSTE.X / .Y)
    "LATITUDE"             DECIMAL(18,10),                -- = Y
    "LONGITUDE"            DECIMAL(18,10),                -- = X

    -- Endereço textual
    "MUNICIPIO"            NVARCHAR(120),
    "UF"                   NVARCHAR(2),
    "LOGRADOURO"           NVARCHAR(200),
    "BAIRRO"               NVARCHAR(120),
    "CEP"                  NVARCHAR(10),

    -- Ocupação pretendida
    "TIPO_OCUPACAO"        NVARCHAR(40),                  -- FIBRA | COAXIAL | ...
    "QTD_PONTOS_FIXACAO"   INTEGER       DEFAULT 1,

    -- Resultado da análise técnica deste poste
    "STATUS_ANALISE"       NVARCHAR(20)  DEFAULT 'PENDENTE', -- PENDENTE | APROVADO | REPROVADO | REVISAR
    "MOTIVO_REPROVACAO"    NVARCHAR(300),
    "GEO_VALIDADA"         NVARCHAR(1)   DEFAULT 'N',      -- lat/long dentro da área de concessão
    "POSTE_LOCALIZADO"     NVARCHAR(1)   DEFAULT 'N',      -- casou com um poste do cadastro
    "OBSERVACAO"           NVARCHAR(1000),

    "CREATED_AT"           LONGDATE CS_LONGDATE,
    "UPDATED_AT"           LONGDATE CS_LONGDATE,

    PRIMARY KEY ("ID_PROJETO_POSTE")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE INDEX "IX_PROJPOSTE_PROJETO"    ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_POSTE" ("ID_PROJETO");
CREATE INDEX "IX_PROJPOSTE_BARRAMENTO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_POSTE" ("BARRAMENTO");
CREATE INDEX "IX_PROJPOSTE_STATUS"     ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_POSTE" ("STATUS_ANALISE");


-- ---------------------------------------------------------------------
-- 3) PROJETO_TIPO_DOCUMENTO  (catálogo — quais documentos são exigidos)
--    Parametrização, no estilo de PORTAL_COMPARTILHAMENTO_ETAPA.
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_TIPO_DOCUMENTO"
(
    "ID_TIPO_DOCUMENTO"    INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "CODIGO"               NVARCHAR(40)  NOT NULL,        -- ex.: PLANILHA_POSTES
    "NOME"                 NVARCHAR(150) NOT NULL,
    "DESCRICAO"            NVARCHAR(500),
    "OBRIGATORIO"          NVARCHAR(1)   DEFAULT 'S',
    "EXTENSOES_ACEITAS"    NVARCHAR(120),                 -- ex.: pdf,xlsx,csv,kml
    "ORDEM"                INTEGER       DEFAULT 0,
    "ATIVO"                NVARCHAR(1)   DEFAULT 'S',
    "CREATED_AT"           LONGDATE CS_LONGDATE,
    "UPDATED_AT"           LONGDATE CS_LONGDATE,

    PRIMARY KEY ("ID_TIPO_DOCUMENTO")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE UNIQUE INDEX "IX_PROJTIPODOC_CODIGO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_TIPO_DOCUMENTO" ("CODIGO");

