-- ---------------------------------------------------------------------
-- 4) PROJETO_DOCUMENTO  (1:N — os arquivos de cada projeto)
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_DOCUMENTO"
(
    "ID_PROJETO_DOCUMENTO" INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "ID_PROJETO"           INTEGER       NOT NULL,
    "ID_SUBMISSAO"         INTEGER,                       -- e-mail que trouxe o arquivo
    "CODIGO_TIPO"          NVARCHAR(40),                  -- = PROJETO_TIPO_DOCUMENTO.CODIGO
    "TIPO_DOCUMENTO"       NVARCHAR(150),                 -- nome amigável (cópia)
    "OBRIGATORIO"          NVARCHAR(1)   DEFAULT 'N',

    "NOME_ARQUIVO"         NVARCHAR(255),
    "TIPO_ARQUIVO"         NVARCHAR(120),                 -- mime/type
    "CAMINHO_ARQUIVO"      NVARCHAR(1000),                -- link SharePoint / storage
    "TAMANHO_BYTES"        BIGINT,
    "HASH_ARQUIVO"         NVARCHAR(64),                  -- sha-256, p/ deduplicar anexos

    "STATUS_DOCUMENTO"     NVARCHAR(20)  DEFAULT 'PENDENTE', -- PENDENTE | RECEBIDO | VALIDADO | REJEITADO
    "MOTIVO_REJEICAO"      NVARCHAR(500),

    "RECEBIDO_VIA"         NVARCHAR(20)  DEFAULT 'EMAIL',
    "EMAIL_REMETENTE"      NVARCHAR(200),
    "DATA_RECEBIMENTO"     LONGDATE CS_LONGDATE,
    "VALIDADO_POR"         NVARCHAR(100),
    "DATA_VALIDACAO"       LONGDATE CS_LONGDATE,

    "OBSERVACAO"           NVARCHAR(1000),
    "CREATED_AT"           LONGDATE CS_LONGDATE,
    "ATIVO"                NVARCHAR(1)   DEFAULT 'S',

    PRIMARY KEY ("ID_PROJETO_DOCUMENTO")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE INDEX "IX_PROJDOC_PROJETO"   ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_DOCUMENTO" ("ID_PROJETO");
CREATE INDEX "IX_PROJDOC_TIPO"      ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_DOCUMENTO" ("CODIGO_TIPO");
CREATE INDEX "IX_PROJDOC_STATUS"    ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_DOCUMENTO" ("STATUS_DOCUMENTO");
CREATE INDEX "IX_PROJDOC_SUBMISSAO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_DOCUMENTO" ("ID_SUBMISSAO");


-- ---------------------------------------------------------------------
-- 5) PROJETO_SUBMISSAO  (1:N — cada e-mail/entrega que alimentou o projeto)
--    Guarda o rastro do e-mail e quem, no portal, fez a triagem.
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_SUBMISSAO"
(
    "ID_SUBMISSAO"         INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "ID_PROJETO"           INTEGER,                       -- nulo enquanto não triado
    "CHAVE_CONEXAO"        NVARCHAR(14),                  -- CNPJ dos dígitos, extraído do e-mail

    -- Dados do e-mail
    "MESSAGE_ID"           NVARCHAR(255),                 -- Message-ID do e-mail (dedupe)
    "EMAIL_REMETENTE"      NVARCHAR(200),
    "EMAIL_PARA"           NVARCHAR(200),                 -- caixa institucional que recebeu
    "ASSUNTO"              NVARCHAR(500),
    "CORPO_RESUMO"         NVARCHAR(4000),
    "DATA_EMAIL"           LONGDATE CS_LONGDATE,
    "QTD_ANEXOS"           INTEGER       DEFAULT 0,

    -- Triagem no portal
    "STATUS_SUBMISSAO"     NVARCHAR(20)  DEFAULT 'NOVO',  -- NOVO | TRIADA | VINCULADA | DESCARTADA
    "MOTIVO_DESCARTE"      NVARCHAR(500),
    "SUBMETIDO_POR"        NVARCHAR(100),                 -- usuário do portal que submeteu/triou
    "DATA_SUBMISSAO"       LONGDATE CS_LONGDATE,
    "PROCESSADO_EM"        LONGDATE CS_LONGDATE,

    "CREATED_AT"           LONGDATE CS_LONGDATE,

    PRIMARY KEY ("ID_SUBMISSAO")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE UNIQUE INDEX "IX_PROJSUB_MSGID"  ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_SUBMISSAO" ("MESSAGE_ID");
CREATE INDEX        "IX_PROJSUB_PROJETO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_SUBMISSAO" ("ID_PROJETO");
CREATE INDEX        "IX_PROJSUB_CHAVE"   ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_SUBMISSAO" ("CHAVE_CONEXAO");
CREATE INDEX        "IX_PROJSUB_STATUS"  ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_SUBMISSAO" ("STATUS_SUBMISSAO");


-- ---------------------------------------------------------------------
-- 6) PROJETO_ANALISE  (1:N — parecer/checklist da análise; permite reanálise)
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_ANALISE"
(
    "ID_ANALISE"          INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "ID_PROJETO"          INTEGER       NOT NULL,

    -- Checklist (S/N/NA)
    "DOC_CONFERIDA"       NVARCHAR(1)   DEFAULT 'N',
    "CNPJ_REGULAR"        NVARCHAR(1)   DEFAULT 'N',
    "LICENCA_ANATEL_OK"   NVARCHAR(1)   DEFAULT 'N',
    "POSTES_LOCALIZADOS"  NVARCHAR(1)   DEFAULT 'N',
    "GEO_DENTRO_CONCESSAO" NVARCHAR(1)  DEFAULT 'N',
    "CAPACIDADE_SUFICIENTE" NVARCHAR(1) DEFAULT 'N',      -- postes têm ponto de fixação livre

    "RESULTADO"           NVARCHAR(20),                   -- APROVADO | APROVADO_PARCIAL | REPROVADO | PENDENCIA
    "PARECER"             NVARCHAR(4000),
    "QTD_POSTES_APROVADOS" INTEGER      DEFAULT 0,
    "QTD_POSTES_REPROVADOS" INTEGER     DEFAULT 0,

    "USUARIO_ANALISE"     NVARCHAR(100),
    "DATA_ANALISE"        LONGDATE CS_LONGDATE,
    "CREATED_AT"          LONGDATE CS_LONGDATE,

    PRIMARY KEY ("ID_ANALISE")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE INDEX "IX_PROJANALISE_PROJETO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_ANALISE" ("ID_PROJETO");


-- ---------------------------------------------------------------------
-- 7) PROJETO_HISTORICO  (trilha de auditoria — 1 linha por evento)
-- ---------------------------------------------------------------------
CREATE COLUMN TABLE "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_HISTORICO"
(
    "ID_HISTORICO"        INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY,
    "ID_PROJETO"          INTEGER       NOT NULL,
    "TIPO_EVENTO"         NVARCHAR(30),                   -- RECEBIMENTO | STATUS | DOCUMENTO | ANALISE | VINCULO | ATRIBUICAO
    "STATUS_ANTERIOR"     NVARCHAR(20),
    "STATUS_NOVO"         NVARCHAR(20),
    "DESCRICAO"           NVARCHAR(1000),
    "USUARIO"             NVARCHAR(100),
    "DATA_EVENTO"         LONGDATE CS_LONGDATE,

    PRIMARY KEY ("ID_HISTORICO")
)
UNLOAD PRIORITY 5 AUTO MERGE;

CREATE INDEX "IX_PROJHIST_PROJETO" ON "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO_HISTORICO" ("ID_PROJETO");


-- =====================================================================
--  VIEW de apoio: projeto + jornada do provedor resolvida pela CHAVE_CONEXAO
--  (útil pra tela "Vínculo" e pra relatórios; não substitui os FKs gravados)
-- =====================================================================
CREATE VIEW "CLB349328"."V_PORTAL_COMPARTILHAMENTO_PROJETO_JORNADA" AS
SELECT
    PJ."ID_PROJETO",
    PJ."NUMERO_PROJETO",
    PJ."CHAVE_CONEXAO",
    PJ."STATUS_PROJETO",
    PJ."CNPJ",
    PJ."RAZAO_SOCIAL",
    PJ."NOME_FANTASIA",
    PR."ID_PROVEDOR",
    PR."STATUS_CADASTRO",
    PC."ID_PROCESSO",
    PC."NUMERO_PROTOCOLO",
    PC."STATUS_ATUAL"           AS "STATUS_PROCESSO",
    PC."ETAPA_ATUAL"
FROM "CLB349328"."PORTAL_COMPARTILHAMENTO_PROJETO" PJ
LEFT JOIN "CLB349328"."PORTAL_COMPARTILHAMENTO_PROVEDOR" PR
    ON REPLACE(REPLACE(REPLACE(PR."CNPJ",'.',''),'/',''),'-','') = PJ."CHAVE_CONEXAO"
LEFT JOIN "CLB349328"."PORTAL_COMPARTILHAMENTO_PROCESSO" PC
    ON PC."ID_PROVEDOR" = PR."ID_PROVEDOR"
   AND (PJ."ID_PROCESSO" IS NULL OR PC."ID_PROCESSO" = PJ."ID_PROCESSO")
WHERE PJ."ATIVO" = 'S';


-- =====================================================================
--  Domínios de valores (validados no backend, não por constraint):
--
--  PROJETO.STATUS_PROJETO :
--    RECEBIDO | EM_ANALISE | PENDENTE_DOC | ANALISE_TECNICA |
--    PARECER_EMITIDO | VINCULADO | CONCLUIDO | DEVOLVIDO | CANCELADO
--  PROJETO.PRIORIDADE : BAIXA | MEDIA | ALTA | URGENTE
--  PROJETO.CANAL_ORIGEM : EMAIL | UPLOAD | API
--
--  PROJETO_POSTE.STATUS_ANALISE : PENDENTE | APROVADO | REPROVADO | REVISAR
--  PROJETO_POSTE.TIPO_OCUPACAO  : FIBRA | COAXIAL | ENERGIA | OUTRO
--
--  PROJETO_DOCUMENTO.STATUS_DOCUMENTO : PENDENTE | RECEBIDO | VALIDADO | REJEITADO
--  PROJETO_DOCUMENTO.RECEBIDO_VIA     : EMAIL | UPLOAD | SHAREPOINT
--
--  PROJETO_SUBMISSAO.STATUS_SUBMISSAO : NOVO | TRIADA | VINCULADA | DESCARTADA
--
--  PROJETO_ANALISE.RESULTADO : APROVADO | APROVADO_PARCIAL | REPROVADO | PENDENCIA
--  PROJETO_HISTORICO.TIPO_EVENTO :
--    RECEBIMENTO | STATUS | DOCUMENTO | ANALISE | VINCULO | ATRIBUICAO
-- =====================================================================
